<?php
declare(strict_types=1);$direction=($_GET['richtung']??'de-fr')==='fr-de'?'fr-de':'de-fr';$topicInput=$_GET['thema']??[];$selectedTopics=is_array($topicInput)?$topicInput:[$topicInput];$selectedTopics=array_values(array_unique(array_filter(array_map(static fn($v):string=>trim((string)$v),$selectedTopics),static fn(string $v):bool=>$v!=='')));$topics=$cardRepository->topics($direction);$countRaw=(string)($_GET['anzahl']??'25');if(!in_array($countRaw,['25','50','100','alle'],true))$countRaw='25';$requested=$countRaw==='alle'?null:(int)$countRaw;$exam=$examService->build($requested,$direction,$selectedTopics);$questions=$exam['questions'];$total=$exam['count'];
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Französisch-Prüfung</title><link rel="stylesheet" href="assets/css/main.css"><link rel="stylesheet" href="assets/css/exam.css"></head><body><main class="exam-page"><div class="exam-wrapper"><?php require __DIR__.'/../partials/public-hero.php';?><section class="exam-config-card"><h2>Prüfung zusammenstellen</h2><form method="get" class="exam-config-form"><input type="hidden" name="action" value="pruefung"><label>Richtung<select name="richtung"><option value="de-fr" <?=$direction==='de-fr'?'selected':''?>>Deutsch → Französisch</option><option value="fr-de" <?=$direction==='fr-de'?'selected':''?>>Französisch → Deutsch</option></select></label><label>Anzahl<select name="anzahl"><?php foreach(['25','50','100','alle'] as $n):?><option value="<?=$n?>" <?=$countRaw===$n?'selected':''?>><?=ucfirst($n)?></option><?php endforeach;?></select></label><label>Themen<div class="lesson-multiselect"><label class="lesson-option lesson-all"><input type="checkbox" id="topic-all" <?=$selectedTopics===[]?'checked':''?>><span>Alle Themen</span></label><?php foreach($topics as $topic):?><label class="lesson-option"><input type="checkbox" name="thema[]" value="<?=Html::e($topic)?>" <?=in_array($topic,$selectedTopics,true)?'checked':''?>><span><?=Html::e($topic)?></span></label><?php endforeach;?></div></label><button class="button button-primary">Prüfung starten</button></form></section><section class="exam-intro"><h2><?=$total?> Fragen</h2><div class="exam-progress-box"><strong id="answered-count">0</strong> / <?=$total?> beantwortet</div></section><?php foreach($questions as $i=>$q):?><section class="exam-question" data-correct="<?=Html::e($q['correct_key'])?>"><div class="exam-question-head"><span class="badge">Frage <?=$i+1?></span><span class="badge">Lektion <?=$q['lektion']?></span></div><h2><?=Html::e($q['frage'])?></h2><div class="exam-options"><?php foreach($q['options'] as $k=>$v):?><button type="button" class="exam-option" data-key="<?=$k?>"><strong><?=$k?></strong><span class="exam-answer"><?=Html::e($v)?></span></button><?php endforeach;?></div><div class="exam-feedback"></div></section><?php endforeach;?><div class="card-actions"><a class="button button-secondary" href="index.php">← Lernkarten</a></div></div></main><script src="assets/js/exam.js"></script><script>document.getElementById('topic-all')?.addEventListener('change',e=>{if(e.target.checked)document.querySelectorAll('input[name="thema[]"]').forEach(x=>x.checked=false);});</script></body></html>
